@@ -1,0 +1,652 @@
+/* ===== CSS Reset & Base ===== */
+*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
+
+:root {
+  --bg-base:       #0a0a0f;
+  --bg-surface:    #111118;
+  --bg-card:       #16161f;
+  --bg-hover:      #1e1e2a;
+  --border:        #2a2a38;
+  --border-light:  #3a3a50;
+  --accent:        #7c5cfc;
+  --accent-glow:   rgba(124, 92, 252, 0.35);
+  --accent-2:      #fc5c7d;
+  --accent-3:      #43e97b;
+  --gold:          #f9c74f;
+  --text-primary:  #f0f0f8;
+  --text-secondary:#a0a0b8;
+  --text-muted:    #606078;
+  --red:           #ff4d6d;
+  --radius-sm:     6px;
+  --radius-md:     12px;
+  --radius-lg:     20px;
+  --shadow-card:   0 4px 24px rgba(0,0,0,0.5);
+  --shadow-glow:   0 0 40px var(--accent-glow);
+  --transition:    0.22s cubic-bezier(0.4,0,0.2,1);
+  --font-sans:     'Inter', system-ui, -apple-system, sans-serif;
+  --font-display:  'Playfair Display', Georgia, serif;
+}
+
+html { scroll-behavior: smooth; }
+
+body {
+  font-family: var(--font-sans);
+  background: var(--bg-base);
+  color: var(--text-primary);
+  min-height: 100vh;
+  line-height: 1.6;
+  -webkit-font-smoothing: antialiased;
+}
+
+img { display: block; width: 100%; height: 100%; object-fit: cover; }
+a { text-decoration: none; color: inherit; }
+button { cursor: pointer; border: none; background: none; font-family: inherit; }
+ul { list-style: none; }
+
+/* ===== Utility ===== */
+.visually-hidden { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0,0,0,0); }
+.tag {
+  display: inline-block;
+  font-size: 11px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase;
+  padding: 3px 10px; border-radius: 99px;
+}
+.tag--accent  { background: var(--accent-glow); color: var(--accent); border: 1px solid var(--accent); }
+.tag--sale    { background: rgba(255,77,109,.15); color: var(--red); border: 1px solid var(--red); }
+.tag--new     { background: rgba(67,233,123,.12); color: var(--accent-3); border: 1px solid var(--accent-3); }
+.tag--gold    { background: rgba(249,199,79,.12); color: var(--gold); border: 1px solid var(--gold); }
+.tag--edit    { background: rgba(252,92,125,.12); color: var(--accent-2); border: 1px solid var(--accent-2); }
+
+/* ===== Scrollbar ===== */
+::-webkit-scrollbar { width: 6px; }
+::-webkit-scrollbar-track { background: var(--bg-base); }
+::-webkit-scrollbar-thumb { background: var(--border-light); border-radius: 3px; }
+
+/* ===== HEADER / NAV ===== */
+#app-header {
+  position: sticky; top: 0; z-index: 100;
+  background: rgba(10,10,15,.82);
+  backdrop-filter: blur(18px) saturate(1.4);
+  -webkit-backdrop-filter: blur(18px) saturate(1.4);
+  border-bottom: 1px solid var(--border);
+}
+
+.nav-inner {
+  max-width: 1320px; margin: 0 auto;
+  display: grid; grid-template-columns: 1fr auto 1fr;
+  align-items: center; gap: 24px;
+  padding: 0 24px; height: 66px;
+}
+
+.nav-logo {
+  font-family: var(--font-display);
+  font-size: 22px; font-weight: 700; letter-spacing: -.02em;
+  background: linear-gradient(130deg, #fff 40%, var(--accent));
+  -webkit-background-clip: text; -webkit-text-fill-color: transparent;
+  white-space: nowrap;
+}
+
+.nav-links {
+  display: flex; gap: 4px;
+}
+.nav-links a {
+  font-size: 13.5px; font-weight: 500; color: var(--text-secondary);
+  padding: 6px 14px; border-radius: var(--radius-sm);
+  transition: color var(--transition), background var(--transition);
+}
+.nav-links a:hover { color: var(--text-primary); background: var(--bg-hover); }
+
+.nav-actions {
+  display: flex; align-items: center; justify-content: flex-end; gap: 8px;
+}
+
+.nav-search {
+  display: flex; align-items: center; gap: 8px;
+  background: var(--bg-surface); border: 1px solid var(--border);
+  border-radius: var(--radius-sm); padding: 7px 14px;
+  transition: border-color var(--transition), box-shadow var(--transition);
+  width: 200px;
+}
+.nav-search:focus-within { border-color: var(--accent); box-shadow: 0 0 0 3px var(--accent-glow); }
+.nav-search input { background: none; border: none; outline: none; color: var(--text-primary); font-size: 13px; width: 100%; }
+.nav-search input::placeholder { color: var(--text-muted); }
+.nav-search svg { color: var(--text-muted); flex-shrink: 0; }
+
+.icon-btn {
+  width: 38px; height: 38px;
+  display: flex; align-items: center; justify-content: center;
+  border-radius: var(--radius-sm);
+  color: var(--text-secondary);
+  transition: color var(--transition), background var(--transition);
+  position: relative;
+}
+.icon-btn:hover { color: var(--text-primary); background: var(--bg-hover); }
+.icon-btn .badge {
+  position: absolute; top: 4px; right: 4px;
+  width: 16px; height: 16px; border-radius: 50%;
+  background: var(--accent); color: #fff;
+  font-size: 9px; font-weight: 700;
+  display: flex; align-items: center; justify-content: center;
+  border: 2px solid var(--bg-base);
+}
+
+/* ===== HERO ===== */
+#hero {
+  position: relative; overflow: hidden;
+  min-height: 580px;
+  display: flex; align-items: center;
+  background: linear-gradient(135deg, #0d0b1e 0%, #0a0a0f 60%, #110a1a 100%);
+}
+
+.hero-bg-orb {
+  position: absolute; border-radius: 50%; filter: blur(90px); pointer-events: none;
+}
+.hero-bg-orb-1 {
+  width: 600px; height: 600px;
+  background: radial-gradient(circle, rgba(124,92,252,.22), transparent 70%);
+  top: -150px; left: -100px;
+}
+.hero-bg-orb-2 {
+  width: 400px; height: 400px;
+  background: radial-gradient(circle, rgba(252,92,125,.16), transparent 70%);
+  bottom: -100px; right: 200px;
+}
+
+.hero-inner {
+  max-width: 1320px; margin: 0 auto; padding: 80px 24px;
+  display: grid; grid-template-columns: 1fr 1fr; gap: 60px; align-items: center;
+  width: 100%;
+}
+
+.hero-eyebrow {
+  display: flex; align-items: center; gap: 10px; margin-bottom: 20px;
+}
+.hero-eyebrow-line {
+  width: 32px; height: 2px;
+  background: linear-gradient(90deg, var(--accent), var(--accent-2));
+  border-radius: 1px;
+}
+.hero-eyebrow span { font-size: 12px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; color: var(--accent); }
+
+.hero-title {
+  font-family: var(--font-display);
