*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg-base:       #0a0a0f;
  --bg-surface:    #111118;
  --bg-card:       #16161f;
  --bg-hover:      #1e1e2a;
  --border:        #2a2a38;
  --border-light:  #3a3a50;
  --accent:        #7c5cfc;
  --accent-glow:   rgba(124, 92, 252, 0.35);
  --accent-2:      #fc5c7d;
  --accent-3:      #43e97b;
  --gold:          #f9c74f;
  --text-primary:  #f0f0f8;
  --text-secondary:#a0a0b8;
  --text-muted:    #606078;
  --red:           #ff4d6d;
  --radius-sm:     6px;
  --radius-md:     12px;
  --radius-lg:     20px;
  --shadow-card:   0 4px 24px rgba(0,0,0,0.5);
  --shadow-glow:   0 0 40px var(--accent-glow);
  --transition:    0.22s cubic-bezier(0.4,0,0.2,1);
  --font-sans:     'Inter', system-ui, -apple-system, sans-serif;
  --font-display:  'Playfair Display', Georgia, serif;
}

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-sans);
  background: var(--bg-base);
  color: var(--text-primary);
  min-height: 100vh;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

img { display: block; width: 100%; height: 100%; object-fit: cover; }
a { text-decoration: none; color: inherit; }
button { cursor: pointer; border: none; background: none; font-family: inherit; }
ul { list-style: none; }

/* ===== Utility ===== */
.visually-hidden { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0,0,0,0); }
.tag {
  display: inline-block;
  font-size: 11px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase;
  padding: 3px 10px; border-radius: 99px;
}
.tag--accent  { background: var(--accent-glow); color: var(--accent); border: 1px solid var(--accent); }
.tag--sale    { background: rgba(255,77,109,.15); color: var(--red); border: 1px solid var(--red); }
.tag--new     { background: rgba(67,233,123,.12); color: var(--accent-3); border: 1px solid var(--accent-3); }
.tag--gold    { background: rgba(249,199,79,.12); color: var(--gold); border: 1px solid var(--gold); }
.tag--edit    { background: rgba(252,92,125,.12); color: var(--accent-2); border: 1px solid var(--accent-2); }

/* ===== Scrollbar ===== */
::-webkit-scrollbar { width: 6px; }
::-webkit-scrollbar-track { background: var(--bg-base); }
::-webkit-scrollbar-thumb { background: var(--border-light); border-radius: 3px; }

/* ===== HEADER / NAV ===== */
#app-header {
  position: sticky; top: 0; z-index: 100;
  background: rgba(10,10,15,.82);
  backdrop-filter: blur(18px) saturate(1.4);
  -webkit-backdrop-filter: blur(18px) saturate(1.4);
  border-bottom: 1px solid var(--border);
}

.nav-inner {
  max-width: 1320px; margin: 0 auto;
  display: grid; grid-template-columns: 1fr auto 1fr;
  align-items: center; gap: 24px;
  padding: 0 24px; height: 66px;
}

.nav-logo {
  font-family: var(--font-display);
  font-size: 22px; font-weight: 700; letter-spacing: -.02em;
  background: linear-gradient(130deg, #fff 40%, var(--accent));
  -webkit-background-clip: text; -webkit-text-fill-color: transparent;
  white-space: nowrap;
}

.nav-links {
  display: flex; gap: 4px;
}
.nav-links a {
  font-size: 13.5px; font-weight: 500; color: var(--text-secondary);
  padding: 6px 14px; border-radius: var(--radius-sm);
  transition: color var(--transition), background var(--transition);
}
.nav-links a:hover { color: var(--text-primary); background: var(--bg-hover); }

.nav-actions {
  display: flex; align-items: center; justify-content: flex-end; gap: 8px;
}

.nav-search {
  display: flex; align-items: center; gap: 8px;
  background: var(--bg-surface); border: 1px solid var(--border);
  border-radius: var(--radius-sm); padding: 7px 14px;
  transition: border-color var(--transition), box-shadow var(--transition);
  width: 200px;
}
.nav-search:focus-within { border-color: var(--accent); box-shadow: 0 0 0 3px var(--accent-glow); }
.nav-search input { background: none; border: none; outline: none; color: var(--text-primary); font-size: 13px; width: 100%; }
.nav-search input::placeholder { color: var(--text-muted); }
.nav-search svg { color: var(--text-muted); flex-shrink: 0; }

.icon-btn {
  width: 38px; height: 38px;
  display: flex; align-items: center; justify-content: center;
  border-radius: var(--radius-sm);
  color: var(--text-secondary);
  transition: color var(--transition), background var(--transition);
  position: relative;
}
.icon-btn:hover { color: var(--text-primary); background: var(--bg-hover); }
.icon-btn .badge {
  position: absolute; top: 4px; right: 4px;
  width: 16px; height: 16px; border-radius: 50%;
  background: var(--accent); color: #fff;
  font-size: 9px; font-weight: 700;
  display: flex; align-items: center; justify-content: center;
  border: 2px solid var(--bg-base);
}

/* ===== HERO ===== */
#hero {
  position: relative; overflow: hidden;
  min-height: 580px;
  display: flex; align-items: center;
  background: linear-gradient(135deg, #0d0b1e 0%, #0a0a0f 60%, #110a1a 100%);
}

.hero-bg-orb {
  position: absolute; border-radius: 50%; filter: blur(90px); pointer-events: none;
}
.hero-bg-orb-1 {
  width: 600px; height: 600px;
  background: radial-gradient(circle, rgba(124,92,252,.22), transparent 70%);
  top: -150px; left: -100px;
}
.hero-bg-orb-2 {
  width: 400px; height: 400px;
  background: radial-gradient(circle, rgba(252,92,125,.16), transparent 70%);
  bottom: -100px; right: 200px;
}

.hero-inner {
  max-width: 1320px; margin: 0 auto; padding: 80px 24px;
  display: grid; grid-template-columns: 1fr 1fr; gap: 60px; align-items: center;
  width: 100%;
}

.hero-eyebrow {
  display: flex; align-items: center; gap: 10px; margin-bottom: 20px;
}
.hero-eyebrow-line {
  width: 32px; height: 2px;
  background: linear-gradient(90deg, var(--accent), var(--accent-2));
  border-radius: 1px;
}
.hero-eyebrow span { font-size: 12px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; color: var(--accent); }

.hero-title {
  font-family: var(--font-display);
  font-size: clamp(38px, 5vw, 62px); font-weight: 700;
  line-height: 1.1; letter-spacing: -.02em;
  margin-bottom: 20px;
}
.hero-title em {
  font-style: normal;
  background: linear-gradient(130deg, var(--accent) 0%, var(--accent-2) 100%);
  -webkit-background-clip: text; -webkit-text-fill-color: transparent;
}

.hero-sub {
  font-size: 16px; color: var(--text-secondary); max-width: 440px; margin-bottom: 36px;
  line-height: 1.7;
}

.hero-ctas {
  display: flex; gap: 14px; flex-wrap: wrap; align-items: center;
}

.btn-primary {
  display: inline-flex; align-items: center; gap: 8px;
  background: var(--accent);
  color: #fff; font-size: 14px; font-weight: 600;
  padding: 13px 26px; border-radius: var(--radius-md);
  transition: opacity var(--transition), box-shadow var(--transition), transform var(--transition);
  box-shadow: 0 4px 20px var(--accent-glow);
}
.btn-primary:hover { opacity: .88; transform: translateY(-1px); box-shadow: 0 8px 28px var(--accent-glow); }

.btn-ghost {
  display: inline-flex; align-items: center; gap: 8px;
  background: transparent;
  color: var(--text-secondary); font-size: 14px; font-weight: 600;
  padding: 12px 22px; border-radius: var(--radius-md);
  border: 1px solid var(--border-light);
  transition: color var(--transition), border-color var(--transition), background var(--transition);
}
.btn-ghost:hover { color: var(--text-primary); border-color: var(--accent); background: var(--bg-hover); }

.hero-stats {
  display: flex; gap: 32px; margin-top: 48px;
  padding-top: 28px; border-top: 1px solid var(--border);
}
.hero-stat-val {
  font-size: 24px; font-weight: 700; color: var(--text-primary); letter-spacing: -.02em;
}
.hero-stat-label { font-size: 12px; color: var(--text-muted); margin-top: 2px; }

.hero-visual {
  position: relative; display: flex; align-items: center; justify-content: center;
}
.hero-product-card {
  background: var(--bg-card); border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden; width: 300px;
  box-shadow: var(--shadow-card), var(--shadow-glow);
  transform: rotate(2deg);
}
.hero-product-card-img {
  height: 340px; background: linear-gradient(145deg, #1a1828 0%, #241f3a 100%);
  display: flex; align-items: center; justify-content: center;
  font-size: 100px;
}
.hero-product-card-body { padding: 20px; }
.hero-product-card-name { font-weight: 600; font-size: 15px; margin-bottom: 6px; }
.hero-product-card-price {
  font-size: 20px; font-weight: 700; color: var(--accent);
}

.hero-badge-float {
  position: absolute; background: var(--bg-card);
  border: 1px solid var(--border); border-radius: var(--radius-md);
  padding: 12px 16px; box-shadow: var(--shadow-card);
  display: flex; align-items: center; gap: 10px;
}
.hero-badge-float-1 { top: 20px; right: -30px; }
.hero-badge-float-2 { bottom: 40px; left: -40px; transform: rotate(-3deg); }
.badge-float-icon { font-size: 22px; }
.badge-float-label { font-size: 11px; color: var(--text-muted); }
.badge-float-val { font-size: 14px; font-weight: 700; }

/* ===== SECTION WRAPPER ===== */
.section {
  padding: 80px 0;
}
.section--alt { background: var(--bg-surface); }

.section-inner {
  max-width: 1320px; margin: 0 auto; padding: 0 24px;
}

.section-header {
  display: flex; align-items: flex-end; justify-content: space-between;
  margin-bottom: 40px; gap: 16px; flex-wrap: wrap;
}
.section-title {
  font-family: var(--font-display);
  font-size: clamp(22px, 3vw, 30px); font-weight: 700; letter-spacing: -.02em;
}
.section-title span {
  background: linear-gradient(130deg, var(--accent), var(--accent-2));
  -webkit-background-clip: text; -webkit-text-fill-color: transparent;
}
.section-sub { font-size: 14px; color: var(--text-muted); margin-top: 6px; }
.section-link {
  font-size: 13px; font-weight: 600; color: var(--accent);
  display: flex; align-items: center; gap: 4px;
  transition: gap var(--transition);
  white-space: nowrap;
}
.section-link:hover { gap: 8px; }

/* ===== CATEGORY PILLS ===== */
.category-strip {
  display: flex; gap: 10px; flex-wrap: wrap; margin-bottom: 40px;
}
.cat-pill {
  display: flex; align-items: center; gap: 8px;
  padding: 9px 18px; border-radius: 99px;
  font-size: 13px; font-weight: 600;
  background: var(--bg-card); border: 1px solid var(--border);
  color: var(--text-secondary);
  transition: all var(--transition);
}
.cat-pill:hover, .cat-pill.active {
  border-color: var(--accent); color: var(--accent); background: var(--bg-hover);
}
.cat-pill span { font-size: 16px; }

/* ===== PRODUCT GRID ===== */
.product-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 22px;
}

.product-card {
  background: var(--bg-card); border: 1px solid var(--border);
  border-radius: var(--radius-lg); overflow: hidden;
  transition: transform var(--transition), box-shadow var(--transition), border-color var(--transition);
  position: relative;
}
.product-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-card), 0 0 30px rgba(124,92,252,.15);
  border-color: var(--border-light);
}

.product-card-img {
  position: relative; aspect-ratio: 1;
  background: linear-gradient(145deg, #131221 0%, #1c1a30 100%);
  display: flex; align-items: center; justify-content: center;
  font-size: 72px;
  overflow: hidden;
}
.product-card-img::after {
  content: ''; position: absolute; inset: 0;
  background: linear-gradient(180deg, transparent 50%, rgba(0,0,0,.4) 100%);
}

.product-card-actions {
  position: absolute; top: 10px; right: 10px;
  display: flex; flex-direction: column; gap: 6px;
  opacity: 0; transform: translateX(8px);
  transition: opacity var(--transition), transform var(--transition);
  z-index: 2;
}
.product-card:hover .product-card-actions { opacity: 1; transform: translateX(0); }

.card-action-btn {
  width: 34px; height: 34px;
  background: rgba(17,17,24,.85); backdrop-filter: blur(8px);
  border: 1px solid var(--border-light); border-radius: var(--radius-sm);
  display: flex; align-items: center; justify-content: center;
  color: var(--text-secondary); font-size: 16px;
  transition: color var(--transition), border-color var(--transition);
}
.card-action-btn:hover { color: var(--accent); border-color: var(--accent); }

.product-card-badge {
  position: absolute; top: 10px; left: 10px; z-index: 2;
}

.product-card-body { padding: 16px; }
.product-card-brand { font-size: 11px; color: var(--text-muted); text-transform: uppercase; letter-spacing: .06em; margin-bottom: 4px; }
.product-card-name { font-size: 14px; font-weight: 600; margin-bottom: 10px; line-height: 1.4; }

.product-card-rating {
  display: flex; align-items: center; gap: 6px; margin-bottom: 12px;
}
.stars { color: var(--gold); font-size: 12px; letter-spacing: 1px; }
.rating-count { font-size: 11px; color: var(--text-muted); }

.product-card-footer {
  display: flex; align-items: center; justify-content: space-between;
}
.price-group { display: flex; align-items: baseline; gap: 8px; }
.price-current { font-size: 17px; font-weight: 700; color: var(--text-primary); }
.price-original { font-size: 13px; color: var(--text-muted); text-decoration: line-through; }
.price-save { font-size: 11px; font-weight: 700; color: var(--accent-3); }

.add-cart-btn {
  width: 34px; height: 34px;
  background: var(--accent); border-radius: var(--radius-sm);
  display: flex; align-items: center; justify-content: center;
  color: #fff; font-size: 18px;
  transition: opacity var(--transition), box-shadow var(--transition), transform var(--transition);
  box-shadow: 0 2px 12px var(--accent-glow);
}
.add-cart-btn:hover { opacity: .85; transform: scale(1.08); }

/* ===== DEALS BANNER ===== */
#deals { background: var(--bg-base); }

.deals-header-accent { color: var(--gold); }

.countdown {
  display: flex; gap: 8px; align-items: center;
}
.countdown-block {
  background: var(--bg-card); border: 1px solid var(--border);
  border-radius: var(--radius-sm); padding: 8px 12px; text-align: center; min-width: 52px;
}
.countdown-val { font-size: 20px; font-weight: 800; font-variant-numeric: tabular-nums; color: var(--text-primary); }
.countdown-label { font-size: 9px; color: var(--text-muted); text-transform: uppercase; letter-spacing: .08em; }
.countdown-sep { font-size: 18px; font-weight: 700; color: var(--text-muted); margin-top: -8px; }

.deals-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
}

@media (max-width: 900px) { .deals-grid { grid-template-columns: 1fr; } }

.deal-card {
  background: var(--bg-card); border: 1px solid var(--border);
  border-radius: var(--radius-lg); overflow: hidden;
  display: grid; grid-template-columns: 1fr 1fr;
  transition: transform var(--transition), box-shadow var(--transition);
}
.deal-card:hover { transform: translateY(-3px); box-shadow: var(--shadow-card); }

.deal-card--wide {
  grid-column: 1 / -1;
  grid-template-columns: 1fr 1fr;
  background: linear-gradient(135deg, #130d2a 0%, #16101e 100%);
  border-color: var(--accent);
  box-shadow: 0 0 0 1px var(--accent), var(--shadow-glow);
}

.deal-card-content { padding: 28px; display: flex; flex-direction: column; justify-content: center; gap: 12px; }
.deal-card-name { font-size: 18px; font-weight: 700; line-height: 1.3; }
.deal-card--wide .deal-card-name { font-family: var(--font-display); font-size: 22px; }
.deal-card-desc { font-size: 13px; color: var(--text-secondary); line-height: 1.6; }
.deal-price { display: flex; align-items: baseline; gap: 10px; }
.deal-price-current { font-size: 24px; font-weight: 800; color: var(--accent); }
.deal-price-original { font-size: 14px; color: var(--text-muted); text-decoration: line-through; }
.deal-discount {
  font-size: 12px; font-weight: 700; color: #fff;
  background: var(--red); padding: 3px 9px; border-radius: 99px;
}
.deal-progress-label { font-size: 11px; color: var(--text-muted); margin-bottom: 5px; }
.deal-progress-bar {
  height: 5px; background: var(--bg-hover); border-radius: 3px; overflow: hidden;
}
.deal-progress-fill {
  height: 100%; border-radius: 3px;
  background: linear-gradient(90deg, var(--accent), var(--accent-2));
}

.deal-card-img {
  background: linear-gradient(145deg, #131221 0%, #1c1a30 100%);
  display: flex; align-items: center; justify-content: center;
  font-size: 80px; min-height: 200px;
}

/* ===== EDITORIAL ===== */
#editorial { background: var(--bg-surface); }

.editorial-grid {
  display: grid;
  grid-template-columns: 1.6fr 1fr 1fr;
  gap: 22px;
}
@media (max-width: 960px) { .editorial-grid { grid-template-columns: 1fr 1fr; } }
@media (max-width: 600px) { .editorial-grid { grid-template-columns: 1fr; } }

.edit-card {
  background: var(--bg-card); border: 1px solid var(--border);
  border-radius: var(--radius-lg); overflow: hidden;
  display: flex; flex-direction: column;
  transition: transform var(--transition), box-shadow var(--transition), border-color var(--transition);
  cursor: pointer;
}
.edit-card:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-card);
  border-color: var(--border-light);
}

.edit-card--featured { grid-row: span 2; }

.edit-card-img {
  flex: 0 0 auto;
  background: linear-gradient(145deg, #0f0e1e 0%, #1a1430 100%);
  display: flex; align-items: center; justify-content: center;
  font-size: 64px; padding: 32px;
}
.edit-card--featured .edit-card-img { font-size: 100px; padding: 60px; min-height: 260px; }

.edit-card-body { padding: 20px; flex: 1; display: flex; flex-direction: column; gap: 10px; }
.edit-card-meta { display: flex; align-items: center; gap: 10px; }
.edit-card-date { font-size: 11px; color: var(--text-muted); }
.edit-card-title { font-weight: 700; font-size: 15px; line-height: 1.4; }
.edit-card--featured .edit-card-title { font-family: var(--font-display); font-size: 20px; }
.edit-card-excerpt { font-size: 13px; color: var(--text-secondary); line-height: 1.6; flex: 1; }
.edit-card-author {
  display: flex; align-items: center; gap: 8px;
  margin-top: 4px; padding-top: 12px; border-top: 1px solid var(--border);
